:root {
  --bg: #07070f;
  --panel: #10121f;
  --line: #1f2440;
  --text: #e8ecff;
  --muted: #7a82a8;
  --cyan: #2de2ff;
  --blue: #2f7bff;
  --red: #ff2d55;
  --green: #2bff88;
  --cols: 6;
  --rows: 8;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  overflow: hidden;
}

body {
  background:
    radial-gradient(ellipse at 50% -10%, rgba(45, 226, 255, 0.12), transparent 60%),
    var(--bg);
}

.app {
  max-width: 480px;
  height: 100dvh;
  margin: 0 auto;
  padding: max(12px, env(safe-area-inset-top)) 16px max(12px, env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
}

.hidden { display: none !important; }

button {
  font: inherit;
  color: var(--text);
  background: var(--blue);
  border: 0;
  border-radius: 10px;
  padding: 12px 18px;
  font-weight: 700;
  letter-spacing: 0.05em;
  cursor: pointer;
  box-shadow: 0 0 14px rgba(47, 123, 255, 0.5);
}
button:active { transform: scale(0.96); }
button.secondary { background: var(--panel); border: 1px solid var(--line); box-shadow: none; }
button.icon { width: 44px; height: 44px; padding: 0; }
button.small { padding: 8px 14px; font-size: 13px; align-self: center; }

.box {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 6px 12px;
  text-align: center;
  min-width: 72px;
}
.box label { display: block; font-size: 10px; color: var(--muted); letter-spacing: 0.15em; }
.box b { font-size: 20px; }

/* ── 스테이지 선택 ── */
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 8px 0 20px;
}
h1 {
  margin: 0;
  font-size: 30px;
  letter-spacing: 0.08em;
  color: var(--cyan);
  text-shadow: 0 0 12px rgba(45, 226, 255, 0.7);
}
h1 span { color: var(--red); text-shadow: 0 0 12px rgba(255, 45, 85, 0.7); margin-left: 4px; }

.stage-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  overflow-y: auto;
}
.stage-btn {
  aspect-ratio: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0;
  font-size: 22px;
  background: var(--panel);
  border: 1px solid var(--cyan);
  box-shadow: 0 0 10px rgba(45, 226, 255, 0.25), inset 0 0 10px rgba(45, 226, 255, 0.1);
}
.stage-btn small { font-size: 11px; color: #ffd84a; letter-spacing: 1px; }
.stage-btn.locked { border-color: var(--line); color: var(--muted); box-shadow: none; }
.stage-btn.locked small { color: var(--muted); }

.legend {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin: auto 0 16px;
  padding-top: 20px;
}
.legend div { display: flex; flex-direction: column; align-items: center; gap: 6px; font-size: 11px; color: var(--muted); letter-spacing: 0.1em; }
.legend .tile { display: block; width: 34px; height: 34px; border-radius: 6px; }
.tile.blue { background: var(--blue); box-shadow: 0 0 12px var(--blue); }
.tile.red { background: var(--red); box-shadow: 0 0 12px var(--red); }
.tile.green { background: var(--green); box-shadow: 0 0 12px var(--green); }

/* ── 게임 화면 ── */
.topbar { display: flex; align-items: center; justify-content: space-between; }
.stage-name { font-weight: 800; letter-spacing: 0.15em; color: var(--cyan); }

.hud { display: flex; justify-content: space-between; gap: 8px; margin: 12px 0 8px; }
.hud .box { flex: 1; }
.lives { color: var(--red); letter-spacing: 2px; }

.timebar { height: 6px; background: var(--panel); border-radius: 3px; overflow: hidden; }
#timeFill { height: 100%; width: 100%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); transition: width 0.2s linear; }
#timeFill.low { background: var(--red); box-shadow: 0 0 8px var(--red); }

.board-wrap {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  touch-action: none;
}
.board {
  position: relative;
  display: grid;
  grid-template-columns: repeat(var(--cols), 1fr);
  grid-template-rows: repeat(var(--rows), 1fr);
  aspect-ratio: var(--cols) / var(--rows);
  height: 100%;
  max-width: 100%;
  max-height: 100%;
  padding: 0;
}
.board.shake { animation: shake 0.3s; }

/* 칸 사이 간격은 ::before 안쪽 여백으로 (플레이어 위치 계산을 단순하게) */
.cell { position: relative; }
.cell::before {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 6px;
  background: #0d0f1c;
  border: 1px solid #1a1f38;
  transition: background 0.08s, box-shadow 0.08s;
}
.cell.hole::before { background: transparent; border-color: transparent; }
.cell.blue::before { background: var(--blue); border-color: #7fb0ff; box-shadow: 0 0 14px rgba(47, 123, 255, 0.8); }
.cell.done::before { background: #142046; border-color: #24366e; }
.cell.green::before { background: rgba(43, 255, 136, 0.85); border-color: #a5ffcc; box-shadow: 0 0 14px rgba(43, 255, 136, 0.7); }
.cell.warn::before { background: rgba(255, 45, 85, 0.25); border-color: rgba(255, 45, 85, 0.6); animation: warn 0.25s infinite alternate; }
.cell.red::before { background: var(--red); border-color: #ff9bb0; box-shadow: 0 0 16px rgba(255, 45, 85, 0.9); }
.cell.pop::after {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 6px;
  border: 2px solid var(--cyan);
  animation: pop 0.35s ease-out forwards;
  pointer-events: none;
}

.player {
  position: absolute;
  left: 0;
  top: 0;
  width: calc(100% / var(--cols));
  height: calc(100% / var(--rows));
  transition: transform 0.08s ease-out;
  pointer-events: none;
  z-index: 2;
}
.player::before {
  content: "";
  position: absolute;
  inset: 22%;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 0 3px var(--cyan), 0 0 18px var(--cyan);
}
.player.invincible { animation: blink 0.15s infinite alternate; }

.countdown {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 0 20px var(--cyan);
  pointer-events: none;
  z-index: 3;
}

.hint { text-align: center; color: var(--muted); font-size: 12px; letter-spacing: 0.2em; margin: 10px 0 0; }

/* ── 모달 ── */
.modal {
  position: fixed;
  inset: 0;
  background: rgba(4, 4, 10, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 10;
}
.panel {
  width: 100%;
  max-width: 320px;
  background: var(--panel);
  border: 1px solid var(--cyan);
  border-radius: 16px;
  padding: 24px;
  text-align: center;
  box-shadow: 0 0 30px rgba(45, 226, 255, 0.3);
}
.panel h2 { margin: 0 0 8px; letter-spacing: 0.15em; color: var(--cyan); }
.panel h2.fail { color: var(--red); }
.panel p { color: var(--muted); margin: 8px 0 18px; }
.stars { font-size: 34px; color: #ffd84a; letter-spacing: 6px; min-height: 0; }
.stars .off { color: #2a2f4a; }
.buttons { display: flex; flex-direction: column; gap: 10px; }

@keyframes pop { from { transform: scale(1); opacity: 1; } to { transform: scale(1.5); opacity: 0; } }
@keyframes warn { from { opacity: 0.4; } to { opacity: 1; } }
@keyframes blink { from { opacity: 1; } to { opacity: 0.2; } }
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-6px); }
