  let d = null;        // 현재 장면 상태
  let timers = [];
  let current = 0;
  let onDone = null;

  function build() {
    boardEl.querySelectorAll('.cell').forEach((c) => c.remove());
    cells = [];
    for (let i = 0; i < N * N; i++) {
      const c = document.createElement('div');
