  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
  await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
  await send('Emulation.setUserAgentOverride', { userAgent: 'Mozilla/5.0 (Linux; Android 14; SM-S921N) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/129.0 Mobile Safari/537.36' });
  await send('Page.navigate', { url: 'https://stages-861a3.web.app/' });
  await sleep(4000);
  console.log('demo visible:', await ev(`!document.getElementById('demoScreen').classList.contains('hidden')`));
  await ev(`document.getElementById('demoSkip').click()`);
  await sleep(500);
  console.log('mode button:', await ev(`(() => { const b = document.getElementById('modeBtn'); const r = b.getBoundingClientRect(); return b.textContent + ' @ y=' + Math.round(r.top) + ' visible=' + (r.height > 0 && r.top >= 0 && r.bottom <= innerHeight); })()`));
  await shot('m-1-stages');
  await ev(`document.querySelector('#stageGrid .stage-btn').click()`);
  await sleep(2500);
  console.log('cells:', await ev(`document.querySelectorAll('#board .cell').length`), 'board size:', await ev(`(() => { const r = document.getElementById('board').getBoundingClientRect(); return Math.round(r.width) + 'x' + Math.round(r.height); })()`));
  await shot('m-2-game');
  console.log('errors:', errors.length ? errors : 'none');
} catch (e) {
  console.log('ERROR', e.message);
} finally {
  ws?.close();
  edge.kill();
}

