const HEX='polygon(25% 6.7%, 75% 6.7%, 100% 50%, 75% 93.3%, 25% 93.3%, 0% 50%)';
patch('style.css',[[
`.player.diag { transition-duration: 0.16s; }
.player::before {
  content: "";
  position: absolute;
  inset: 22%;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 0 3px var(--cyan), 0 0 18px var(--cyan);
}`,
`.player.diag { transition-duration: 0.16s; }
/* 육각형 플레이어
   - 테두리 빛·그림자는 잘린 모양(clip-path)을 따라가도록 filter로
   - ::before = 면이 나뉜 몸체. 한 칸마다 60°씩 굴러감 (--rot, game.js/demo.js가 지정)
   - ::after  = 고정된 조명(왼쪽 위) + 밟은 칸 색 반사(--tint). 육각형은 60° 대칭이라 다 구르면 모양이 딱 겹침 */
.player {
  --tint: transparent;
  filter: drop-shadow(0 0 5px rgba(45, 226, 255, 0.9)) drop-shadow(0 3px 3px rgba(0, 0, 0, 0.6));
}
.player::before,
.player::after {
  content: "";
  position: absolute;
  inset: 18%;
  clip-path: ${HEX};
}
.player::before {
  /* 6개 옆면(살짝 다른 밝기) + 가운데 윗면 */
  background:
    radial-gradient(circle, #f6fbff 0 30%, transparent 31%),
    conic-gradient(from -30deg, #e3eef6 0 60deg, #c9d8e4 60deg 120deg, #dbe7f0 120deg 180deg,
      #c3d3e0 180deg 240deg, #d7e4ee 240deg 300deg, #ccdbe7 300deg 360deg);
  transform: rotate(var(--rot, 0deg));
  transition: transform 0.16s cubic-bezier(0.3, 0.7, 0.4, 1);
}
.player::after {
  background:
    radial-gradient(circle at 68% 72%, var(--tint) 0%, transparent 65%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.6) 0%, rgba(255, 255, 255, 0) 45%, rgba(10, 30, 60, 0.35) 100%);
  transition: background 0.15s;
}
.player[data-tint="blue"] { --tint: rgba(47, 123, 255, 0.6); }
.player[data-tint="green"] { --tint: rgba(43, 255, 136, 0.55); }
.player[data-tint="red"] { --tint: rgba(255, 45, 85, 0.65); }`]]);

// 게임: 구르기 + 반사색
patch('game.js',[
[`    playerEl.classList.toggle('diag', dx !== 0 && dy !== 0); // 대각선은 거리가 길어서 애니메이션도 조금 길게`,
