patch('style.css',[[`.player.invincible { animation: blink 0.15s infinite alternate; }`,
`.player.invincible { animation: blink 0.15s infinite alternate; }

/* 금: 생명이 줄 때마다 늘어남 (data-crack = 잃은 생명 수). 몸체와 같이 굴러감 */
.player .crack {
  position: absolute;
  inset: 18%;
  width: 64%;
  height: 64%;
  clip-path: polygon(25% 6.7%, 75% 6.7%, 100% 50%, 75% 93.3%, 25% 93.3%, 0% 50%);
  transform: rotate(var(--rot, 0deg));
  transition: transform 0.16s cubic-bezier(0.3, 0.7, 0.4, 1);
  z-index: 1;
  overflow: visible;
}
.player .crack path {
  fill: none;
  stroke: #142233;
  stroke-width: 3;
  stroke-linejoin: round;
  stroke-linecap: round;
  filter: drop-shadow(1px 1px 0 rgba(255, 255, 255, 0.75)); /* 갈라진 틈의 밝은 단면 */
}
.player .crack g { opacity: 0; transition: opacity 0.1s; }
.player[data-crack="1"] .c1,
.player[data-crack="2"] .c1,
.player[data-crack="2"] .c2 { opacity: 1; }
.player.crack-flash .crack { animation: crack-flash 0.35s ease-out; }

/* 깨짐: 몸체는 숨기고 6조각이 흩어짐 */
.player.shatter::before,
.player.shatter::after,
.player.shatter .crack { opacity: 0; }
.player .shard {
  position: absolute;
  inset: 18%;
  background: linear-gradient(135deg, #f4f9fd, #a9bdcd);
  animation: shard 0.75s cubic-bezier(0.2, 0.7, 0.4, 1) forwards;
}

@keyframes crack-flash { 0% { filter: brightness(2.2); } 100% { filter: brightness(1); } }
@keyframes shard {
  0% { transform: translate(0, 0) rotate(0deg); opacity: 1; }
  100% { transform: translate(var(--dx), var(--dy)) rotate(var(--r)); opacity: 0; }
}`]]);

