const fs=require('fs');
const patch=(p,rep)=>{let s=fs.readFileSync(p,'utf8');for(const [a,b] of rep){if(s.split(a).length!==2)throw new Error(p+' miss '+a.slice(0,50));s=s.replace(a,()=>b);}fs.writeFileSync(p,s);};
let g=fs.readFileSync('game.js','utf8');
const start=g.indexOf('  // 육각형 깨짐: 6개 면이 각자 바깥쪽으로 흩어짐');
const end=g.indexOf('  function restorePlayer() {');
g=g.slice(0,start)+`  // ── 육각형 깨짐 ──
  // 실제 유리처럼: 충격 지점에서 방사형 금 8~11갈래 → 각 쐐기를 들쭉날쭉한 선으로 안/바깥 두 조각으로
  // → 매번 다른 모양·크기의 조각 16~22개 + 작은 가루. 좌표는 육각형 상자 기준 % (0~100)
  const HEX_POINTS = [[25, 6.7], [75, 6.7], [100, 50], [75, 93.3], [25, 93.3], [0, 50]];
  const rand = (a, b) => a + Math.random() * (b - a);

  // P에서 각도 a로 뻗은 선이 육각형 테두리와 만나는 점
  function rayToEdge(P, a) {
    const d = [Math.cos(a), Math.sin(a)];
    let best = null;
    HEX_POINTS.forEach((A, k) => {
      const B = HEX_POINTS[(k + 1) % 6];
      const e = [B[0] - A[0], B[1] - A[1]];
      const den = d[0] * e[1] - d[1] * e[0];
      if (Math.abs(den) < 1e-9) return;
      const t = ((A[0] - P[0]) * e[1] - (A[1] - P[1]) * e[0]) / den;
      const u = ((A[0] - P[0]) * d[1] - (A[1] - P[1]) * d[0]) / den;
      if (t > 0 && u >= 0 && u <= 1 && (!best || t < best.t)) best = { t, p: [P[0] + d[0] * t, P[1] + d[1] * t] };
    });
    return best.p;
  }

  function fracture() {
    const P = [50 + rand(-10, 10), 50 + rand(-10, 10)];
    const n = 8 + Math.floor(Math.random() * 4);
    const step = (Math.PI * 2) / n;
    const offset = rand(0, step);
    const rays = [];
    for (let i = 0; i < n; i++) {
      const a = offset + i * step + rand(-0.35, 0.35) * step;
      const edge = rayToEdge(P, a);
      const r = rand(0.3, 0.62); // 안쪽 조각을 자르는 위치 (이웃 쐐기와 공유해야 틈이 안 생김)
      rays.push({ a, edge, mid: [P[0] + (edge[0] - P[0]) * r, P[1] + (edge[1] - P[1]) * r] });
    }
    // 각 꼭짓점의 P 기준 각도 (쐐기 사이에 낀 꼭짓점을 테두리에 포함하려고)
    const verts = HEX_POINTS.map((v) => ({ v, a: Math.atan2(v[1] - P[1], v[0] - P[0]) }));
    const pieces = [];
    for (let i = 0; i < n; i++) {
      const A = rays[i];
      const B = rays[(i + 1) % n];
      const a0 = A.a;
      let a1 = B.a;
      while (a1 <= a0) a1 += Math.PI * 2;
      const between = verts
        .map(({ v, a }) => { let x = a; while (x <= a0) x += Math.PI * 2; return { v, a: x }; })
        .filter(({ a }) => a < a1)
        .sort((p, q) => p.a - q.a)
        .map(({ v }) => v);
      // 안/바깥 경계를 들쭉날쭉하게: 두 자르는 점 사이에 살짝 어긋난 점 하나
      const J = [(A.mid[0] + B.mid[0]) / 2 + rand(-4, 4), (A.mid[1] + B.mid[1]) / 2 + rand(-4, 4)];
      pieces.push([P, A.mid, J, B.mid]);
      pieces.push([A.mid, A.edge, ...between, B.edge, B.mid, J]);
    }
    // 가루: 작은 삼각형 몇 개
    for (let i = 0; i < 6; i++) {
      const c = [P[0] + rand(-14, 14), P[1] + rand(-14, 14)];
      const s = rand(2, 4);
      pieces.push([[c[0], c[1] - s], [c[0] + s, c[1] + s * 0.8], [c[0] - s * 0.9, c[1] + s * 0.6]]);
    }
    return { P, pieces };
  }

  function shatterPlayer() {
    sfx.shatter();
    vibrate([30, 30, 120]);
    restorePlayer();
    // 충격 순간: 금이 꽉 찬 채로 번쩍 → 조각
    playerEl.dataset.crack = '2';
    playerEl.classList.add('crack-flash');
    setTimeout(() => {
      if (!state || state.phase !== 'breaking') return;
      playerEl.classList.add('shatter');
      const { P, pieces } = fracture();
      const size = playerEl.getBoundingClientRect().width || 60; // 조각이 날아가는 거리를 칸 크기에 맞춤
      pieces.forEach((poly) => {
        const c = poly.reduce((acc, p) => [acc[0] + p[0] / poly.length, acc[1] + p[1] / poly.length], [0, 0]);
        let dir = [c[0] - P[0], c[1] - P[1]];
        const len = Math.hypot(dir[0], dir[1]) || 1;
        dir = [dir[0] / len, dir[1] / len];
        const dust = poly.length === 3 && Math.abs(poly[0][0] - poly[1][0]) < 6;
        const dist = size * (dust ? rand(0.9, 1.4) : rand(0.35, 0.7) * (0.6 + len / 60));
        const shard = document.createElement('div');
        shard.className = 'shard';
        shard.style.clipPath = \`polygon(\${poly.map((p) => \`\${p[0].toFixed(1)}% \${p[1].toFixed(1)}%\`).join(', ')})\`;
        shard.style.transformOrigin = \`\${c[0].toFixed(1)}% \${c[1].toFixed(1)}%\`;
        const light = Math.round(rand(200, 245));
        shard.style.background = \`linear-gradient(\${Math.round(rand(0, 360))}deg, rgb(\${light + 8}, \${light + 10}, 255), rgb(\${light - 70}, \${light - 50}, \${light - 30}))\`;
        shard.style.setProperty('--dx', \`\${(dir[0] * dist).toFixed(1)}px\`);
        shard.style.setProperty('--dy', \`\${(dir[1] * dist - rand(0, size * 0.15)).toFixed(1)}px\`);
        shard.style.setProperty('--fall', \`\${(size * rand(0.3, 0.7)).toFixed(1)}px\`);
        shard.style.setProperty('--r', \`\${Math.round(rand(-240, 240))}deg\`);
        shard.style.setProperty('--dur', \`\${rand(0.6, 0.95).toFixed(2)}s\`);
        playerEl.appendChild(shard);
      });
    }, 90);
  }

`+g.slice(end);
