        shard.className = 'shard';
        shard.style.clipPath = `polygon(${poly.map((q) => `${f(q[0])}% ${f(q[1])}%`).join(', ')})`;
        shard.style.transformOrigin = `${f(c[0])}% ${f(c[1])}%`;
