// 시작 안내 흐름 확인: 시연 → 개인정보처리방침 → 체크하면 다음 실행부터 안 뜸
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const DIR = process.argv[2];
const PORT = 9420 + Math.floor(Math.random() * 50);
const URL_ = 'file:///D:/Gitasin/cybercube/www/index.html';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const edge = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--user-data-dir=${DIR}/edge-intro`,
  `--remote-debugging-port=${PORT}`, '--allow-file-access-from-files', 'about:blank']);
let ws;
try {
  let target;
  for (let i = 0; i < 40 && !target; i++) {
    await sleep(250);
    try { target = (await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()).find((t) => t.type === 'page'); } catch {}
  }
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener('open', r));
  let id = 0;
  const pending = new Map();
  const errors = [];
  ws.addEventListener('message', (e) => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
    if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text);
  });
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result?.value;
  const shot = async (name) => writeFileSync(`${DIR}/${name}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'));
  const screen = () => ev(`['stageScreen','gameScreen','demoScreen','privacyScreen'].filter((s) => !document.getElementById(s).classList.contains('hidden')).join()`);

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
  await send('Emulation.setUserAgentOverride', { userAgent: 'Mozilla/5.0 (Linux; Android 14) Mobile', acceptLanguage: 'ko' });

  // 1) 처음 실행: 시연 (체크 상자 보임)
  await send('Page.navigate', { url: URL_ });
  await sleep(2000);
  console.log('1st launch      →', await screen(), '| demo checkbox visible:', await ev(`!document.querySelector('#demoScreen .intro-check').classList.contains('hidden')`));
  await ev(`document.getElementById('demoSkip').click()`);
  await sleep(1500);
  console.log('after SKIP      →', await screen(), '| iframe:', await ev(`document.getElementById('privacyFrame').getAttribute('src')`));
  await shot('intro-privacy');
  // 체크 안 하고 시작 → 다음 실행에도 떠야 함
  await ev(`document.getElementById('privacyOk').click()`);
  await sleep(300);
  console.log('after START     →', await screen());
  await send('Page.reload');
  await sleep(2000);
  console.log('2nd launch (no check)  →', await screen());

  // 2) 시연 화면에서 체크 → 개인정보 화면 체크 상자도 같이 체크됨
  await ev(`(() => { const b = document.querySelector('#demoScreen .hide-intro'); b.click(); })()`);
  await ev(`document.getElementById('demoSkip').click()`);
  await sleep(800);
  console.log('checked on demo → privacy checkbox synced:', await ev(`document.querySelector('#privacyScreen .hide-intro').checked`));
  await ev(`document.getElementById('privacyOk').click()`);
  await send('Page.reload');
  await sleep(2000);
  console.log('3rd launch (checked)   →', await screen());

  // 3) ? 버튼: 시연만, 체크 상자 숨김, 건너뛰면 스테이지로
  await ev(`document.getElementById('helpBtn').click()`);
  await sleep(500);
  console.log('? button        →', await screen(), '| checkbox hidden:', await ev(`document.querySelector('#demoScreen .intro-check').classList.contains('hidden')`));
  await ev(`document.getElementById('demoSkip').click()`);
  await sleep(300);
  console.log('? then SKIP     →', await screen());
  console.log('errors:', errors.length ? errors : 'none');
} catch (e) {
  console.log('ERROR', e.message);
} finally {
  ws?.close();
  edge.kill();
}

