  const DIAGONAL_BAND = { straight: [25, 65], diagonal: [15, 75] };
  function move8(dx, dy, wasDiagonal = false) {
    const [min, max] = DIAGONAL_BAND[wasDiagonal ? 'diagonal' : 'straight'];
