// 육각형 → 사람 캐릭터로 교체 (style.css, index.html, game.js, demo.js, sound.js)
const fs = require('fs');
process.chdir(process.argv[2]);
const patch = (p, rep) => {
  let s = fs.readFileSync(p, 'utf8');
  for (const [a, b] of rep) {
    if (s.split(a).length !== 2) throw new Error(p + ' miss ' + a.slice(0, 60));
    s = s.replace(a, () => b);
  }
  fs.writeFileSync(p, s);
};

// ── CSS: 육각형 블록 → 캐릭터 ──
let css = fs.readFileSync('style.css', 'utf8');
const a = css.indexOf('/* ── 육각형 플레이어 ──');
const b = css.indexOf('.countdown {');
if (a < 0 || b < 0) throw new Error('css markers');
const HERO_CSS = fs.readFileSync(process.argv[3], 'utf8');
css = css.slice(0, a) + HERO_CSS + '\n' + css.slice(b);
fs.writeFileSync('style.css', css);

// ── HTML ──
let h = fs.readFileSync('index.html', 'utf8');
const hexRe = /\n {10}<div class="hex">\n {12}<svg class="crack" viewBox="0 0 100 100" aria-hidden="true"><\/svg>\n {10}<\/div>\n {8}/g;
let n = 0;
h = h.replace(hexRe, () => { n++; return ''; });
if (n !== 2) throw new Error('html hex ' + n);
if (h.split('  <script src="crack.js"></script>').length !== 2) throw new Error('html crack script');
h = h.replace('  <script src="crack.js"></script>', '  <script src="hero.js"></script>');
fs.writeFileSync('index.html', h);

// ── 게임 ──
let g = fs.readFileSync('game.js', 'utf8');
const ga = g.indexOf('  // ── 육각형 금·깨짐 (모양 계산과 조각은 crack.js) ──');
const gb = g.indexOf('  // 막힌 방향으로 밀면');
if (ga < 0 || gb < 0) throw new Error('game markers');
g = g.slice(0, ga) + `  // ── 캐릭터 (그림과 동작은 hero.js) ──
  // 생명 0: 번쩍 하고 바닥에 털썩 쓰러짐
  function collapsePlayer() {
    sfx.sizzle();
    vibrate([30, 30, 120]);
    window.Hero.hurt(playerEl);
    setTimeout(() => {
      if (!state || state.phase !== 'breaking') return;
      window.Hero.down(playerEl);
      sfx.fall();
    }, 180);
  }

  // 판 시작·이어하기: 다시 일어선 모습으로 (모습은 render가 생명에 맞춰 바꿈)
  function restorePlayer() {
    window.Hero.reset(playerEl);
  }

` + g.slice(gb);
const gr = g.indexOf('  // 육각형 굴리기:');
const END = '  window.rollPlayer = rollPlayer; // 시연 화면에서도 같이 씀';
const ge = g.indexOf(END);
if (gr < 0 || ge < 0) throw new Error('roll markers');
g = g.slice(0, gr) + `  // 한 칸 이동: 그쪽을 보고 팔다리를 흔들며 뜀
  function stepPlayer(el, dx, dy) {
    window.Hero.step(el, dx, dy);
  }
  window.stepPlayer = stepPlayer; // 시연 화면에서도 같이 씀` + g.slice(ge + END.length);
fs.writeFileSync('game.js', g);
patch('game.js', [
  ['    rollPlayer(playerEl, dx, dy);', '    stepPlayer(playerEl, dx, dy);'],
  ['      shatterPlayer();', '      collapsePlayer();'],
  ['      sfx.crack();', '      sfx.sizzle();\n      window.Hero.hurt(playerEl); // 탄 것처럼 번쩍 + 연기 (모습은 render가 생명에 맞춰 바꿈)'],
  [`    const crack = String(Math.min(2, MAX_LIVES - state.lives));
    if (playerEl.dataset.crack !== crack) {
      if (Number(crack) > Number(playerEl.dataset.crack || 0)) {
        playerEl.classList.remove('crack-flash');
        void playerEl.offsetWidth;
        playerEl.classList.add('crack-flash');
      }
      playerEl.dataset.crack = crack;
    }`, '    window.Hero.setHp(playerEl, state.lives);'],
  ['  buildBoard();\n  if (introHidden())', '  window.Hero.mount(playerEl);\n  buildBoard();\n  if (introHidden())'],
]);

// ── 시연 ──
patch('demo.js', [
  ['    playerEl.dataset.crack = String(Math.min(2, 3 - d.lives));', '    window.Hero.setHp(playerEl, d.lives);'],
  ['      window.rollPlayer?.(playerEl, dx, dy);', '      window.stepPlayer?.(playerEl, dx, dy);'],
  ['    window.Crack.reset(playerEl); // 장면마다 깨끗한 육각형 + 새 금 모양', '    window.Hero.reset(playerEl); // 장면마다 멀쩡한 모습으로'],
  ['  function build() {\n', '  function build() {\n    window.Hero.mount(playerEl);\n'],
  ["      actions.badge('-♥', 'bad');", "      window.Hero.hurt(playerEl);\n      actions.badge('-♥', 'bad');"],
]);

// ── 효과음: 금·깨짐 → 타는 소리·쓰러지는 소리 ──
let snd = fs.readFileSync('sound.js', 'utf8');
const sa = snd.indexOf('    crack() {');
const sb = snd.indexOf('    flatline() {');
if (sa < 0 || sb < 0) throw new Error('sound markers');
snd = snd.slice(0, sa) + `    sizzle() {
      // 탄 소리: "치이익" (높은 잡음이 내려오며 사그라듦) + 작은 "팍"
      noise({ dur: 0.5, vol: 0.14, type: 'bandpass', freq: 6000, sweepTo: 2200, q: 1.5, echo: 0.2 });
      noise({ dur: 0.06, vol: 0.12, type: 'lowpass', freq: 900, echo: 0 });
    },
    fall() {
      // 털썩: 둔하게 바닥에 부딪히는 소리 두 번 (몸 → 머리)
      tone({ f: 95, slide: 45, dur: 0.25, type: 'sine', vol: 0.22, attack: 0.004, echo: 0.1 });
      noise({ dur: 0.16, vol: 0.18, type: 'lowpass', freq: 420, echo: 0.05 });
      tone({ f: 120, slide: 60, dur: 0.15, type: 'sine', vol: 0.12, delay: 0.13, attack: 0.004, echo: 0.1 });
      noise({ dur: 0.1, vol: 0.1, delay: 0.13, type: 'lowpass', freq: 500, echo: 0 });
    },
` + snd.slice(sb);
snd = snd.replace('{ step, blue, hit, crack, shatter, flatline,', '{ step, blue, hit, sizzle, fall, flatline,');
fs.writeFileSync('sound.js', snd);
fs.unlinkSync('crack.js');
console.log('ok');

