// 플레이어 캐릭터: 관절이 있는 사람 (게임·시연 화면 공용)
// - Hero.mount(el)         캐릭터 SVG를 넣음 (그라데이션 id가 겹치지 않게 el.id를 앞에 붙임)
// - Hero.step(el, dx, dy)  한 칸 이동: 그쪽을 보고 달림
// - Hero.setHp(el, hp)     남은 생명에 맞는 모습 (3 멀쩡 / 2 머리카락 탐 / 1 옷이 너덜너덜 / 0 쓰러짐)
// - Hero.hurt(el)          빨강에 닿은 순간: 움찔 + 주황빛 번쩍 + 연기
// - Hero.down(el)          무릎이 꺾이며 뒤로 털썩 쓰러짐
// - Hero.reset(el)         판 시작: 멀쩡하게 서 있는 모습
//
// 그림: 오른쪽을 보는 옆모습(3/4), 약 4.5등신. 왼쪽은 좌우 뒤집기
// 관절 (viewBox 좌표, 회전 기준점은 style.css의 transform-origin과 같아야 함)
//   목 (20.8, 15.2)  어깨 (20.6, 17.6)  팔꿈치 (20.6, 25)
//   엉덩이 (20.5, 31.5)  무릎 (20.5, 41.6)  발목 (20.5, 52)  발바닥 55
(() => {
  // 뒤쪽 팔다리는 조금 어둡게 (back 클래스)
  const leg = (side) => `
    <g class="h-thigh ${side}">
      <rect x="18.5" y="30" width="4" height="12.4" rx="2" class="h-jeans ${side}"/>
      <path class="h-rip" d="M18.9 37.6 l0.9 1.2 l0.8 -1 l0.9 1.4 l0.8 -1.1 l0.6 0.9 v1.6 h-4 z"/>
      <g class="h-shin ${side}">
        <rect x="18.8" y="40.8" width="3.4" height="11.8" rx="1.7" class="h-jeans ${side}"/>
        <path class="h-rip h-rip-hem" d="M18.8 49.6 l0.7 1.1 l0.6 -0.9 l0.7 1.2 l0.7 -1 l0.7 0.8 v1.8 h-3.4 z"/>
        <g class="h-foot ${side}">
          <path class="h-shoe ${side}" d="M18.6 51.6 Q18.6 50.8 19.6 50.8 L21.6 50.8 Q22.6 51 23.4 52 L25.2 52.8 Q26.2 53.4 26 54.4 L25.8 55 L18.6 55 Z"/>
          <path class="h-sole" d="M18.6 54.2 L25.9 54.2"/>
        </g>
      </g>
    </g>`;
  const arm = (side) => `
    <g class="h-uarm ${side}">
      <rect x="19.1" y="16.4" width="3" height="9.2" rx="1.5" class="h-skin ${side}"/>
      <path class="h-sleeve ${side}" d="M18.7 17.2 Q18.7 15.9 20.6 15.9 Q22.5 15.9 22.5 17.2 L22.6 21.4 L18.6 21.4 Z"/>
      <path class="h-sleeve-torn ${side}" d="M18.7 17.2 Q18.7 15.9 20.6 15.9 Q22.5 15.9 22.5 17.2 L22.5 19.6 L21.8 18.8 L21.1 20.2 L20.4 19 L19.7 20.3 L18.7 19.4 Z"/>
      <g class="h-farm ${side}">
        <rect x="19.35" y="24.4" width="2.5" height="7.6" rx="1.25" class="h-skin ${side}"/>
        <ellipse cx="20.6" cy="32.4" rx="1.45" ry="1.6" class="h-skin ${side}"/>
      </g>
    </g>`;

  const SVG = `
<svg class="hero" viewBox="0 0 40 56" aria-hidden="true">
  <defs>
    <linearGradient id="ID-skin" x1="0" x2="1"><stop offset="0" stop-color="#e9b48a"/><stop offset="0.55" stop-color="#f7cfaa"/><stop offset="1" stop-color="#e0a67c"/></linearGradient>
    <linearGradient id="ID-shirt" x1="0" x2="1"><stop offset="0" stop-color="#1fb7d4"/><stop offset="0.5" stop-color="#36e2ff"/><stop offset="1" stop-color="#18a2bd"/></linearGradient>
    <linearGradient id="ID-jeans" x1="0" x2="1"><stop offset="0" stop-color="#1d2c56"/><stop offset="0.5" stop-color="#2d4382"/><stop offset="1" stop-color="#1a274c"/></linearGradient>
    <linearGradient id="ID-hair" x1="0" y1="0" x2="0.4" y2="1"><stop offset="0" stop-color="#6b4228"/><stop offset="0.6" stop-color="#3f2617"/><stop offset="1" stop-color="#2a180e"/></linearGradient>
    <radialGradient id="ID-scalp" cx="0.4" cy="0.3" r="0.8"><stop offset="0" stop-color="#ffe2c6"/><stop offset="1" stop-color="#e3a77d"/></radialGradient>
  </defs>
  <ellipse class="h-shadow" cx="21" cy="55" rx="7.5" ry="1.4"/>
  <g class="h-body">
    ${leg('back')}
    <g class="h-torso">
      ${arm('back')}
      <!-- 목 -->
      <rect x="19.5" y="12.6" width="2.6" height="4" rx="1" class="h-skin h-neck"/>
      <!-- 멀쩡한 티셔츠 -->
      <path class="h-shirt" d="M16.2 18 Q16.4 15.7 18.6 15.4 L23 15.4 Q25.4 15.7 25.3 18.2 L24.8 28.6 Q24.6 30.5 22.6 30.6 L18.2 30.6 Q16.2 30.5 16.2 28.6 Z"/>
      <path class="h-shirt-shade" d="M23.6 16.2 Q25.1 17 25 18.6 L24.6 28.4 Q24.4 29.8 23.3 30.2 Z"/>
      <path class="h-collar" d="M19.2 15.5 Q20.8 17.3 22.6 15.5"/>
      <!-- 너덜너덜한 티셔츠 (생명 1 이하) -->
      <path class="h-shirt-torn" d="M16.2 18 Q16.4 15.7 18.6 15.4 L23 15.4 Q25.4 15.7 25.3 18.2 L24.9 27 L24.1 26.1 L23.6 28.4 L22.6 26.9 L21.8 29.3 L20.8 27.2 L19.8 29 L18.9 26.8 L18 28.6 L17.1 26.5 L16.2 27.4 Z"/>
      <g class="h-burn-holes">
        <ellipse cx="18.6" cy="20.6" rx="1.3" ry="1" class="h-hole"/>
        <ellipse cx="22.8" cy="23.6" rx="1" ry="0.8" class="h-hole"/>
        <ellipse cx="20.2" cy="25.6" rx="0.7" ry="0.55" class="h-hole"/>
        <path class="h-soot" d="M17 22 q2 -1.4 4 0.4 q2 1.4 3.4 -0.6 v2.6 q-1.8 1 -3.6 0 q-2 -1 -3.8 0.4 z"/>
      </g>
      <!-- 벨트 -->
      <rect x="16.2" y="29.2" width="8.6" height="1.7" rx="0.4" class="h-belt"/>
      <rect x="22.6" y="29.1" width="1.6" height="1.9" rx="0.3" class="h-buckle"/>
      <!-- 머리 -->
      <g class="h-head">
        <ellipse cx="21" cy="8.6" rx="5.4" ry="5.8" class="h-skin h-face"/>
        <path class="h-jaw" d="M18 12.2 Q21 15 25 12.4 Q23.6 14.6 21 14.6 Q18.9 14.4 18 12.2 Z"/>
        <ellipse cx="18.4" cy="9.4" rx="1.1" ry="1.5" class="h-skin h-ear"/>
        <path class="h-ear-in" d="M18.2 8.8 q0.6 0.5 0.1 1.2"/>
        <path class="h-nose" d="M26.2 8.6 Q27.2 10.2 26 10.6"/>
        <!-- 머리카락 (생명 3) -->
        <g class="h-hair">
