import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const DIR = process.argv[2];
const PORT = 9520 + Math.floor(Math.random() * 40);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const edge = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--user-data-dir=${DIR}/edge-revive`, `--remote-debugging-port=${PORT}`, 'about:blank']);
let ws;
try {
  let target;
  for (let i = 0; i < 40 && !target; i++) { await sleep(250); try { target = (await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()).find((t) => t.type === 'page'); } catch {} }
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((r) => ws.addEventListener('open', r));
  let id = 0; const pending = new Map(); const errors = [];
  ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.exception?.description); });
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result.result?.value;
  const shot = async (name) => writeFileSync(`${DIR}/${name}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'));
  const waitFor = async (expr, ms) => { const end = Date.now() + ms; while (Date.now() < end) { if (await ev(expr)) return true; await sleep(150); } throw new Error('timeout ' + expr); };
  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
  await send('Page.navigate', { url: 'file:///D:/Gitasin/cybercube/www/index.html' });
  await sleep(800);
  await ev(`localStorage.setItem('cybercube.progress', JSON.stringify({stars:{},best:{},name:'T',sound:false})); localStorage.setItem('cybercube.hideIntro','1'); localStorage.setItem('cybercube.lang','ko'); localStorage.setItem('cybercube.adMode','release'); 1`);
  await send('Page.reload'); await sleep(1200);
  await ev(`document.querySelector('#stageGrid .stage-btn').click()`);
  await sleep(2400);
  // 빨강이 오가는 줄(4번째 줄)에 서서 계속 맞기
  for (let k = 0; k < 3; k++) { await ev(`document.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowUp' }))`); await sleep(150); }
  const modalOpen = `!document.getElementById('modal').classList.contains('hidden')`;
  const firstBtn = `(() => { const b = document.querySelector('#modalButtons button'); const h = b.querySelector('.heart'); return b.textContent + ' | heart color: ' + (h ? getComputedStyle(h).color : 'none'); })()`;
  for (let round = 1; round <= 3; round++) {
    await waitFor(modalOpen, 45000);
    console.log(`fail #${round}:`, await ev(`document.getElementById('modalText').textContent`), '→', await ev(firstBtn));
    if (round === 1) await shot('revive-modal');
    if (round === 3) break;
    await sleep(500); // 창이 뜬 직후 0.4초는 버튼이 안 눌림
    await ev(`document.querySelector('#modalButtons button').click()`);
    await waitFor(`!document.getElementById('adClose').classList.contains('hidden')`, 9000);
    await ev(`document.getElementById('adClose').click()`);
    await sleep(300);
    console.log(`  after ad → lives:`, await ev(`document.getElementById('lives').textContent`));
  }
  console.log('errors:', errors.length ? errors : 'none');
} catch (e) { console.log('ERROR', e.message); } finally { ws?.close(); edge.kill(); }
EOF
