// 특급(EXPERT) 12스테이지를 stages.js에 추가 (시간은 파랑 수로 계산)
const fs = require('fs');
const path = process.argv[2];
let src = fs.readFileSync(path, 'utf8');

const SHUFFLE = [1.5, 3.5];
const S = [
  { // 1 십자 쓸기: 가로·세로 쓸기 + 빠른 튕기기 + 추격
    map: ['B.B.BB', '.B..B.', 'B.GG.B', '.B..B.', 'B.B.B.', '.B..B.', 'B.GG.B', '..P...'],
    hazards: [
      { type: 'sweep', axis: 'row', pos: 0, dir: 1, speed: 1.6 },
      { type: 'sweep', axis: 'col', pos: 0, dir: 1, speed: 1.4 },
      { type: 'bounce', x: 0, y: 3, dx: 1, dy: 0, speed: 5 },
      { type: 'chase', x: 5, y: 0, speed: 2.2 },
    ],
  },
  { // 2 방 나누기: 구멍 벽에 문 하나씩 + 방마다 추격자
    map: ['BB#BBB', 'B.#..B', 'B...#.', '##.###', 'B.B..B', '.B#B.B', 'BG#.GB', '..P...'],
    hazards: [
      { type: 'chase', x: 5, y: 0, speed: 2.2 },
      { type: 'chase', x: 0, y: 4, speed: 2 },
      { type: 'bounce', x: 0, y: 2, dx: 1, dy: 0, speed: 4.5 },
    ],
  },
  { // 3 깜빡이 체크무늬 + 추격
    map: ['BabaBa', 'abBbab', 'Ba.aBb', 'bG.bGa', 'aBab.B', 'babaBa', 'BabBab', '..P...'],
    blink: { period: 1.7, warn: 0.4 },
    hazards: [{ type: 'chase', x: 5, y: 7, speed: 2 }],
  },
  { // 4 가로·세로 쓸기 + 튕기기 둘
    map: ['BG.B.B', 'B.B.GB', '.B.B..', 'G.B.B.', '.B.B.G', '..B.B.', 'BG.B.B', 'G.P..G'],
    hazards: [
      { type: 'sweep', axis: 'row', pos: 0, dir: 1, speed: 1.6 },
      { type: 'sweep', axis: 'col', pos: 5, dir: -1, speed: 1.5 },
      { type: 'bounce', x: 0, y: 2, dx: 1, dy: 0, speed: 5 },
      { type: 'bounce', x: 5, y: 5, dx: -1, dy: 0, speed: 5 },
    ],
  },
  { // 5 대각선 폭풍
    map: ['B.B.B.', '.B.B.B', 'B.G.B.', '.B.B.B', 'B.B.G.', '.B.B.B', 'B.B.B.', '..P...'],
    hazards: [
      { type: 'bounce', x: 1, y: 0, dx: 1, dy: 1, speed: 5 },
      { type: 'bounce', x: 4, y: 0, dx: -1, dy: 1, speed: 5 },
      { type: 'bounce', x: 0, y: 3, dx: 1, dy: -1, speed: 4.5 },
      { type: 'bounce', x: 5, y: 4, dx: -1, dy: 1, speed: 4.5 },
      { type: 'chase', x: 5, y: 6, speed: 1.8 },
    ],
  },
  { // 6 나선형 구멍
    map: ['B.B.B.', '.####B', 'B#.B#.', '.#B.#B', 'B#..#.', '.#B##B', 'B.....', 'BBP.GB'],
    hazards: [
      { type: 'chase', x: 0, y: 0, speed: 2.4 },
      { type: 'bounce', x: 5, y: 6, dx: -1, dy: 0, speed: 5 },
      { type: 'bounce', x: 0, y: 2, dx: 0, dy: 1, speed: 4 },
    ],
  },
  { // 7 쓸기 통로
    map: ['BGBBGB', 'B....B', '.BGGB.', 'B....B', 'B.BB.B', '.BGGB.', 'B....B', 'BGP.GB'],
    hazards: [
      { type: 'sweep', axis: 'row', pos: 0, dir: 1, speed: 1.5 },
      { type: 'sweep', axis: 'col', pos: 0, dir: 1, speed: 1.4 },
      { type: 'bounce', x: 1, y: 3, dx: 1, dy: 0, speed: 5 },
    ],
  },
  { // 8 추격자 셋
    map: ['B..B.B', '.BG..B', 'B..B.B', '.B.G..', 'B.B..B', '..B.B.', 'BG..B.', 'B.P.BB'],
    hazards: [
      { type: 'chase', x: 0, y: 0, speed: 2.1 },
      { type: 'chase', x: 5, y: 0, speed: 1.9 },
      { type: 'chase', x: 5, y: 3, speed: 1.7 },
    ],
  },
  { // 9 깜빡이 + 쓸기 + 추격
    map: ['BaBbBa', 'b.G.Bb', 'aBabBa', 'B.G.bB', 'bBaB.a', 'a.Gb.B', 'BbBaBb', '..P...'],
    blink: { period: 1.7, warn: 0.4 },
    hazards: [
      { type: 'sweep', axis: 'col', pos: 0, dir: 1, speed: 1.4 },
      { type: 'chase', x: 5, y: 1, speed: 1.9 },
    ],
  },
  { // 10 문 하나뿐인 통로 + 층마다 빠른 튕기기
    map: ['BBB.BB', '##.###', 'B.B.GB', '###.##', 'BB.B.B', '#.####', 'BGB.BB', '..P...'],
    hazards: [
      { type: 'bounce', x: 0, y: 0, dx: 1, dy: 0, speed: 5.5 },
      { type: 'bounce', x: 0, y: 2, dx: 1, dy: 0, speed: 5 },
      { type: 'bounce', x: 5, y: 4, dx: -1, dy: 0, speed: 5 },
      { type: 'bounce', x: 5, y: 6, dx: -1, dy: 0, speed: 4 },
    ],
  },
  { // 11 모든 것
    map: ['BGaBbB', 'b.#.aB', 'B.Bb.G', 'a#.B#b', 'B.aB.B', 'bB.#Ba', 'BGbaBG', '..P...'],
    blink: { period: 1.6, warn: 0.4 },
    hazards: [
      { type: 'sweep', axis: 'row', pos: 0, dir: 1, speed: 1.6 },
      { type: 'chase', x: 3, y: 0, speed: 2.2 },
      { type: 'bounce', x: 1, y: 4, dx: 1, dy: 0, speed: 5 },
      { type: 'bounce', x: 0, y: 1, dx: 1, dy: 1, speed: 4.5 },
    ],
  },
  { // 12 마지막 판
    map: ['BGBaBG', 'aB.#Bb', 'B.bBa.', '#BG.Gb', 'Ba.Bb#', '.bB.aB', 'GBabBG', '..P...'],
    blink: { period: 1.5, warn: 0.4 },
    hazards: [
      { type: 'sweep', axis: 'row', pos: 0, dir: 1, speed: 1.7 },
      { type: 'sweep', axis: 'col', pos: 5, dir: -1, speed: 1.5 },
      { type: 'chase', x: 3, y: 2, speed: 2.3 },
      { type: 'bounce', x: 0, y: 5, dx: 1, dy: 0, speed: 5.5 },
      { type: 'bounce', x: 5, y: 2, dx: 0, dy: 1, speed: 4 },
    ],
  },
];

const fmtHazard = (h) => {
  if (h.type === 'sweep') return `{ type: 'sweep', axis: '${h.axis}', pos: ${h.pos}, dir: ${h.dir}, speed: ${h.speed} }`;
  if (h.type === 'chase') return `{ type: 'chase', x: ${h.x}, y: ${h.y}, speed: ${h.speed} }`;
  return `{ type: 'bounce', x: ${h.x}, y: ${h.y}, dx: ${h.dx}, dy: ${h.dy}, speed: ${h.speed} }`;
};
const blocks = S.map((s) => {
  const blue = s.map.join('').split('B').length - 1;
  const time = Math.ceil((blue * 4.5 + 10) / 5) * 5; // 파랑 1개당 약 4.5초 + 여유 10초
  const lines = ['  {', `    time: ${time},`, `    shuffle: [${SHUFFLE.join(', ')}],`, '    map: ['];
  s.map.forEach((r) => lines.push(`      '${r}',`));
  lines.push('    ],');
  if (s.blink) lines.push(`    blink: { period: ${s.blink.period}, warn: ${s.blink.warn} },`);
  lines.push('    hazards: [');
  s.hazards.forEach((h) => lines.push(`      ${fmtHazard(h)},`));
  lines.push('    ],', '  },');
  console.log(`X${S.indexOf(s) + 1}`.padEnd(4), 'blue', blue, 'time', time);
  return lines.join('\n');
});

const EXPERT = `// ── 특급 (EXPERT): 더 빠른 빨강·추격자 셋·십자 쓸기·빠른 깜빡이, 파랑 이동 타이밍 랜덤 1.5~3.5초 ──
const EXPERT = [
${blocks.join('\n')}
];

`;
const marker = '// 난이도 구간';
if (src.split(marker).length !== 2) throw new Error('marker');
src = src.replace(marker, () => EXPERT + marker);
src = src.replace('// 난이도 구간 (스테이지 번호는 0부터 이어짐: 초급 0~11, 중급 12~23, 고급 24~35)',
  '// 난이도 구간 (스테이지 번호는 0부터 이어짐: 초급 0~11, 중급 12~23, 고급 24~35, 특급 36~47)');
const tiers = "  { name: 'HARD', stages: HARD },\n";
if (src.split(tiers).length !== 2) throw new Error('tiers');
src = src.replace(tiers, () => tiers + "  { name: 'EXPERT', stages: EXPERT },\n");
fs.writeFileSync(path, src);

